	function gerarLote($cobranca_lote_id) {
		
		$this->pdf = PDF_new();
		
		$this->iniciaDocumento();
		$this->carregaFontes();
		
		$cobrancas_lote = $this->buscaCobrancasLote($cobranca_lote_id);
		
