	function escreveDetalhamento() {
		
		$this->setFonte("Helvetica-Bold", 7);
		
		$posicao = self::ENDERECO_INICIO + $this->endereco_altura + 2 + 6 + 4;
		
		$this->escreveLinha("Descrição", self::MARGEM_LATERAL + 2, $posicao);
		$this->escreveLinha("Período de Utilização", self::PAGINA_LARGURA - self::MARGEM_LATERAL - 76, $posicao);
		$this->escreveLinhaDireita("Valor Original", self::PAGINA_LARGURA - self::MARGEM_LATERAL - 22, $posicao);
		$this->escreveLinhaDireita("Valor Final", self::PAGINA_LARGURA - self::MARGEM_LATERAL - 2, $posicao);
		
		$posicao += 4;

		$linhas = 1;
		$i = 1;
		
		$this->setFonte("Helvetica", 7);
		
		foreach ($this->dados["detalhamento"] as $detalhamento) {
			
			if ($this->dados["detalhamento"] <= 31 || $i <= 30 || $i == count($this->dados["detalhamento"])) {

				if ($i == count($this->dados["detalhamento"])) {
					$this->setFonte("Helvetica-Bold", 7);
				}
				
				if ($linhas % 2 == 1) {
					PDF_setcolor($this->pdf, "fill", "cmyk", 0.04, 0.02, 0.00, 0.00);
					$this->desenhaQuadrado(self::MARGEM_LATERAL + 1, $posicao - 3, self::PAGINA_LARGURA - (self::MARGEM_LATERAL * 2) - 2, 4);
				}
				
				PDF_setcolor($this->pdf, "fill", "cmyk", 1.00, 1.00, 1.00, 1.00);
				
				if ($i == 30) {
					$this->escreveLinha("...", self::MARGEM_LATERAL + 2 + ($detalhamento["filho"] ? 5 : 0), $posicao);
					$this->escreveLinha("...", self::PAGINA_LARGURA - self::MARGEM_LATERAL - 76, $posicao);
					$this->escreveLinhaDireita("...", self::PAGINA_LARGURA - self::MARGEM_LATERAL - 22, $posicao);
					$this->escreveLinhaDireita("...", self::PAGINA_LARGURA - self::MARGEM_LATERAL - 2, $posicao);
				} else {
					$this->escreveLinha($detalhamento["descricao"], self::MARGEM_LATERAL + 2 + ($detalhamento["filho"] ? 5 : 0), $posicao);
					$this->escreveLinha($detalhamento["periodo"], self::PAGINA_LARGURA - self::MARGEM_LATERAL - 76, $posicao);
					$this->escreveLinhaDireita($detalhamento["valor_original"], self::PAGINA_LARGURA - self::MARGEM_LATERAL - 22, $posicao);
					$this->escreveLinhaDireita($detalhamento["valor_final"], self::PAGINA_LARGURA - self::MARGEM_LATERAL - 2, $posicao);
				}
				
				$posicao += 4;
				$linhas++;
			
			}
			
			$i++;

		}

	}
	
