	}
	
	function desenhaCodigoBarrasCEP($inicio) {
		
		$tabela = array(
			0 => "11000",
			1 => "00011",
			2 => "00101",
			3 => "00110",
			4 => "01001",
			5 => "01010",
			6 => "01100",
			7 => "10001",
			8 => "10010",
			9 => "10100"
		);
		
		$cep = sprintf("%02s", preg_replace("/[^0-9]/", "", $this->dados["cep"]));
		$soma = 0;
		
		for ($i = 0; $i < 8; $i++) {
			$soma += $cep[$i];
		}
		
		$dv = $soma % 10;
		$dv = $dv == 0 ? 0 : 10 - $dv;
		$cep = "{$cep}{$dv}";
		
		$this->posicao_barra_cep_atual = 0;
		
		$this->desenhaBarraCEP($inicio, "1");
		
		for ($i = 0; $i < 9; $i++) {
			for ($j = 0; $j < 5; $j++) {
				$this->desenhaBarraCEP($inicio, $tabela[$i][$j]);
			}
		}
		
		$this->desenhaBarraCEP($inicio, "1");
		
	}
	
	function desenhaBarraCEP($inicio, $tipo) {
		
		if ($tipo == "0") {
			$offset_y = self::BARRA_CEP_ALTA - self::BARRA_CEP_CURTA;
			$altura = self::BARRA_CEP_CURTA;
		} else {
			$offset_y = 0;
			$altura = self::BARRA_CEP_ALTA;
		}
		
		$this->desenhaQuadrado($this->posicao_barra_cep + $this->posicao_barra_cep_atual, $inicio + 4 + $offset_y, self::BARRA_CEP_LARGURA, $altura);
		
		$this->posicao_barra_cep_atual += self::BARRA_CEP_LARGURA + self::BARRA_CEP_ESPACAMENTO;
		
	}
	
