	function desenhaDestaques() {

		PDF_setcolor($this->pdf, "fill", "cmyk", 0.04, 0.02, 0.00, 0.00);

		$largura = (self::PAGINA_LARGURA - (self::MARGEM_LATERAL * 2) - (2 * 3)) / 4;
		
		for ($i = 0; $i < 4; $i++) {
			$this->desenhaQuadrado(self::MARGEM_LATERAL + ($largura * $i) + (2 * $i), self::MARGEM_SUPERIOR + 15, $largura, 11);
		}
		
		if ($this->dados["qrcode"]) {
			$this->desenhaQuadrado(self::MARGEM_LATERAL, self::ENDERECO_INICIO + $this->endereco_altura - 8, self::PAGINA_LARGURA - (self::MARGEM_LATERAL * 2), 8);
		}
		
		$this->desenhaQuadrado(self::MARGEM_LATERAL, self::ENDERECO_INICIO + $this->endereco_altura + 2, self::PAGINA_LARGURA - (self::MARGEM_LATERAL * 2), 6);
		$this->desenhaQuadrado(self::PAGINA_LARGURA - self::MARGEM_LATERAL - $this->largura_colunas[5], self::BOLETO_INICIO + 8, $this->largura_colunas[5], 54);

		PDF_setcolor($this->pdf, "fill", "cmyk", 1.00, 1.00, 1.00, 1.00);

	}

	function desenhaLinhasCapa() {
		
