		$this->desenhaLinha(self::MARGEM_LATERAL + 5, 187, self::PAGINA_LARGURA - self::MARGEM_LATERAL - 5, 187);
		
		// Para uso dos Correios
		
		$this->desenhaLinha(self::MARGEM_LATERAL + 5, self::PAGINA_ALTURA - 40, self::PAGINA_LARGURA - self::MARGEM_LATERAL - 5, self::PAGINA_ALTURA - 40);
		$this->desenhaLinha(self::MARGEM_LATERAL + 5, self::PAGINA_ALTURA - 35.5, self::PAGINA_LARGURA - self::MARGEM_LATERAL - 5, self::PAGINA_ALTURA - 35.5);
		$this->desenhaLinha(self::MARGEM_LATERAL + 5, self::PAGINA_ALTURA - 10, self::PAGINA_LARGURA - self::MARGEM_LATERAL - 5, self::PAGINA_ALTURA - 10);
		
		$this->desenhaLinha(self::MARGEM_LATERAL + 5, self::PAGINA_ALTURA - 40, self::MARGEM_LATERAL + 5, self::PAGINA_ALTURA - 10);
		$this->desenhaLinha(self::PAGINA_LARGURA - self::MARGEM_LATERAL - 5, self::PAGINA_ALTURA - 40, self::PAGINA_LARGURA - self::MARGEM_LATERAL - 5, self::PAGINA_ALTURA - 10);
		$this->desenhaLinha(self::PAGINA_LARGURA - self::MARGEM_LATERAL - 5 - 40, self::PAGINA_ALTURA - 35.5, self::PAGINA_LARGURA - self::MARGEM_LATERAL - 5 - 40, self::PAGINA_ALTURA - 10);
		$this->desenhaLinha(self::PAGINA_LARGURA - self::MARGEM_LATERAL - 5 - 85, self::PAGINA_ALTURA - 35.5, self::PAGINA_LARGURA - self::MARGEM_LATERAL - 5 - 85, self::PAGINA_ALTURA - 10);

		$this->setLarguraLinha(self::LINHA_FINA);
		
		$this->desenhaLinha(self::PAGINA_LARGURA - self::MARGEM_LATERAL - 5 - 85, self::PAGINA_ALTURA - 22.75, self::PAGINA_LARGURA - self::MARGEM_LATERAL - 5, self::PAGINA_ALTURA - 22.75);
		
		
		$altura_quadrado = 3.875;
		
		for ($i = 0; $i < 4; $i++) {
			$this->desenhaLinha(self::MARGEM_LATERAL + 5 + 2, self::PAGINA_ALTURA - 35.5 + 2 + (2 + $altura_quadrado) * $i, self::MARGEM_LATERAL + 5 + 2 + 4, self::PAGINA_ALTURA - 35.5 + 2 + (2 + $altura_quadrado) * $i);
			$this->desenhaLinha(self::MARGEM_LATERAL + 5 + 2, self::PAGINA_ALTURA - 35.5 + 2 + $altura_quadrado + (2 + $altura_quadrado) * $i, self::MARGEM_LATERAL + 5 + 2 + 4, self::PAGINA_ALTURA - 35.5 + 2 + $altura_quadrado + (2 + $altura_quadrado) * $i);
			$this->desenhaLinha(self::MARGEM_LATERAL + 5 + 2, self::PAGINA_ALTURA - 35.5 + 2 + (2 + $altura_quadrado) * $i, self::MARGEM_LATERAL + 5 + 2, self::PAGINA_ALTURA - 35.5 + 2 + $altura_quadrado + (2 + $altura_quadrado) * $i);
			$this->desenhaLinha(self::MARGEM_LATERAL + 5 + 2 + 4, self::PAGINA_ALTURA - 35.5 + 2 + (2 + $altura_quadrado) * $i, self::MARGEM_LATERAL + 5 + 2 + 4, self::PAGINA_ALTURA - 35.5 + 2 + $altura_quadrado + (2 + $altura_quadrado) * $i);
		}
		
		for ($i = 0; $i < 4; $i++) {
			$this->desenhaLinha(self::MARGEM_LATERAL + 5 + 50, self::PAGINA_ALTURA - 35.5 + 2 + (2 + $altura_quadrado) * $i, self::MARGEM_LATERAL + 5 + 50 + 4, self::PAGINA_ALTURA - 35.5 + 2 + (2 + $altura_quadrado) * $i);
			$this->desenhaLinha(self::MARGEM_LATERAL + 5 + 50, self::PAGINA_ALTURA - 35.5 + 2 + $altura_quadrado + (2 + $altura_quadrado) * $i, self::MARGEM_LATERAL + 5 + 50 + 4, self::PAGINA_ALTURA - 35.5 + 2 + $altura_quadrado + (2 + $altura_quadrado) * $i);
			$this->desenhaLinha(self::MARGEM_LATERAL + 5 + 50, self::PAGINA_ALTURA - 35.5 + 2 + (2 + $altura_quadrado) * $i, self::MARGEM_LATERAL + 5 + 50, self::PAGINA_ALTURA - 35.5 + 2 + $altura_quadrado + (2 + $altura_quadrado) * $i);
			$this->desenhaLinha(self::MARGEM_LATERAL + 5 + 50 + 4, self::PAGINA_ALTURA - 35.5 + 2 + (2 + $altura_quadrado) * $i, self::MARGEM_LATERAL + 5 + 50 + 4, self::PAGINA_ALTURA - 35.5 + 2 + $altura_quadrado + (2 + $altura_quadrado) * $i);
		}
		
	}
	
	function desenhaLinhas($desenhar_cerrilhado) {
		
		// Linhas Tracejadas
		
		if ($desenhar_cerrilhado && self::MARGEM_LATERAL > 10) {
			
			$this->setLarguraLinha(0.1, true);
			
			$this->desenhaLinha(10, 0, 10, self::PAGINA_ALTURA);
			$this->desenhaLinha(self::PAGINA_LARGURA - 10, 0, self::PAGINA_LARGURA - 10, self::PAGINA_ALTURA);
			
			$this->desenhaLinha(0, 79, 10, 79);
			$this->desenhaLinha(self::PAGINA_LARGURA, 79, self::PAGINA_LARGURA - 10, 79);
			
			$this->desenhaLinha(0, 190, 10, 190);
			$this->desenhaLinha(self::PAGINA_LARGURA, 190, self::PAGINA_LARGURA - 10, 190);
			
		}
		
		// Cabeçalho
		
		$this->setLarguraLinha(self::LINHA_GROSSA);
		
		$largura = (self::PAGINA_LARGURA - (self::MARGEM_LATERAL * 2) - (2 * 3)) / 4;
		
		for ($i = 0; $i < 4; $i++) {

			$this->desenhaLinha(self::MARGEM_LATERAL + ($largura * $i) + (2 * $i), self::MARGEM_SUPERIOR + 15, self::MARGEM_LATERAL + ($largura * $i) + (2 * $i) + $largura, self::MARGEM_SUPERIOR + 15);
			$this->desenhaLinha(self::MARGEM_LATERAL + ($largura * $i) + (2 * $i), self::MARGEM_SUPERIOR + 26, self::MARGEM_LATERAL + ($largura * $i) + (2 * $i) + $largura, self::MARGEM_SUPERIOR + 26);
			
			$this->desenhaLinha(self::MARGEM_LATERAL + ($largura * $i) + (2 * $i), self::MARGEM_SUPERIOR + 15, self::MARGEM_LATERAL + ($largura * $i) + (2 * $i), self::MARGEM_SUPERIOR + 26);
			$this->desenhaLinha(self::MARGEM_LATERAL + ($largura * $i) + (2 * $i) + $largura, self::MARGEM_SUPERIOR + 15, self::MARGEM_LATERAL + ($largura * $i) + (2 * $i) + $largura, self::MARGEM_SUPERIOR + 26);
			
		}

		// Endereço
		
		$this->setLarguraLinha(self::LINHA_GROSSA);
		
		// Horizontais Grossas
		
		$this->desenhaLinha(self::MARGEM_LATERAL, self::ENDERECO_INICIO, self::PAGINA_LARGURA - self::MARGEM_LATERAL, self::ENDERECO_INICIO);
		$this->desenhaLinha(self::MARGEM_LATERAL, self::ENDERECO_INICIO + $this->endereco_altura, self::PAGINA_LARGURA - self::MARGEM_LATERAL, self::ENDERECO_INICIO + $this->endereco_altura);
				
		if ($this->dados["qrcode"]) {
			$this->desenhaLinha(self::MARGEM_LATERAL, self::ENDERECO_INICIO + $this->endereco_altura - 19, self::PAGINA_LARGURA - self::MARGEM_LATERAL - 37, self::ENDERECO_INICIO + $this->endereco_altura - 19);
			$this->desenhaLinha(self::MARGEM_LATERAL, self::ENDERECO_INICIO + 37, self::PAGINA_LARGURA - self::MARGEM_LATERAL, self::ENDERECO_INICIO + 37);
		}
		
		// Verticais Grossas
		
		$this->desenhaLinha(self::MARGEM_LATERAL, self::ENDERECO_INICIO, self::MARGEM_LATERAL, self::ENDERECO_INICIO + $this->endereco_altura);
		$this->desenhaLinha(self::PAGINA_LARGURA - self::MARGEM_LATERAL, self::ENDERECO_INICIO, self::PAGINA_LARGURA - self::MARGEM_LATERAL, self::ENDERECO_INICIO + $this->endereco_altura);
		
		if ($this->dados["qrcode"]) {
			$this->desenhaLinha(self::PAGINA_LARGURA - self::MARGEM_LATERAL - 37, self::ENDERECO_INICIO, self::PAGINA_LARGURA - self::MARGEM_LATERAL - 37, self::ENDERECO_INICIO + 37);
		}
		
		// Quadro detalhamento

		$this->setLarguraLinha(self::LINHA_GROSSA);

		$this->desenhaLinha(self::MARGEM_LATERAL, self::ENDERECO_INICIO + $this->endereco_altura + 2, self::PAGINA_LARGURA - self::MARGEM_LATERAL, self::ENDERECO_INICIO + $this->endereco_altura + 2);
		$this->desenhaLinha(self::MARGEM_LATERAL, self::ENDERECO_INICIO + $this->endereco_altura + 6 + 2, self::PAGINA_LARGURA - self::MARGEM_LATERAL, self::ENDERECO_INICIO + $this->endereco_altura + 6 + 2);
		$this->desenhaLinha(self::MARGEM_LATERAL, self::BOLETO_INICIO - 2, self::PAGINA_LARGURA - self::MARGEM_LATERAL, self::BOLETO_INICIO - 2);
		
		$this->desenhaLinha(self::MARGEM_LATERAL, self::ENDERECO_INICIO + $this->endereco_altura + 2, self::MARGEM_LATERAL, self::BOLETO_INICIO - 2);
		$this->desenhaLinha(self::PAGINA_LARGURA - self::MARGEM_LATERAL, self::ENDERECO_INICIO + $this->endereco_altura + 2, self::PAGINA_LARGURA - self::MARGEM_LATERAL, self::BOLETO_INICIO - 2);

		// Boleto

		$this->setLarguraLinha(self::LINHA_GROSSA);

		// Horizontais Grossas

		$this->desenhaLinha(self::MARGEM_LATERAL, self::BOLETO_INICIO, self::PAGINA_LARGURA - self::MARGEM_LATERAL, self::BOLETO_INICIO);
		$this->desenhaLinha(self::MARGEM_LATERAL, self::BOLETO_INICIO + 8, self::PAGINA_LARGURA - self::MARGEM_LATERAL, self::BOLETO_INICIO + 8);
		$this->desenhaLinha(self::MARGEM_LATERAL, self::BOLETO_INICIO + 62, self::PAGINA_LARGURA - self::MARGEM_LATERAL, self::BOLETO_INICIO + 62);
		$this->desenhaLinha(self::MARGEM_LATERAL, self::BOLETO_INICIO + 74, self::PAGINA_LARGURA - self::MARGEM_LATERAL, self::BOLETO_INICIO + 74);
		
		// Verticais Grossas

		$this->desenhaLinha(self::MARGEM_LATERAL, self::BOLETO_INICIO, self::MARGEM_LATERAL, self::BOLETO_INICIO + 74);
		$this->desenhaLinha(self::PAGINA_LARGURA - self::MARGEM_LATERAL - $this->largura_colunas[5], self::BOLETO_INICIO + 8, self::PAGINA_LARGURA - self::MARGEM_LATERAL - $this->largura_colunas[5], self::BOLETO_INICIO + 62);
		$this->desenhaLinha(self::PAGINA_LARGURA - self::MARGEM_LATERAL, self::BOLETO_INICIO, self::PAGINA_LARGURA - self::MARGEM_LATERAL, self::BOLETO_INICIO + 74);

		$this->setLarguraLinha(self::LINHA_FINA);

		// Horizontais Finas

		$this->desenhaLinha(self::MARGEM_LATERAL, self::BOLETO_INICIO + 14, self::PAGINA_LARGURA - self::MARGEM_LATERAL, self::BOLETO_INICIO + 14);
		$this->desenhaLinha(self::MARGEM_LATERAL, self::BOLETO_INICIO + 20, self::PAGINA_LARGURA - self::MARGEM_LATERAL, self::BOLETO_INICIO + 20);
		$this->desenhaLinha(self::MARGEM_LATERAL, self::BOLETO_INICIO + 26, self::PAGINA_LARGURA - self::MARGEM_LATERAL, self::BOLETO_INICIO + 26);
		$this->desenhaLinha(self::MARGEM_LATERAL, self::BOLETO_INICIO + 32, self::PAGINA_LARGURA - self::MARGEM_LATERAL, self::BOLETO_INICIO + 32);

		$this->desenhaLinha(self::PAGINA_LARGURA - self::MARGEM_LATERAL - $this->largura_colunas[5], self::BOLETO_INICIO + 38, self::PAGINA_LARGURA - self::MARGEM_LATERAL, self::BOLETO_INICIO + 38);
		$this->desenhaLinha(self::PAGINA_LARGURA - self::MARGEM_LATERAL - $this->largura_colunas[5], self::BOLETO_INICIO + 44, self::PAGINA_LARGURA - self::MARGEM_LATERAL, self::BOLETO_INICIO + 44);
		$this->desenhaLinha(self::PAGINA_LARGURA - self::MARGEM_LATERAL - $this->largura_colunas[5], self::BOLETO_INICIO + 50, self::PAGINA_LARGURA - self::MARGEM_LATERAL, self::BOLETO_INICIO + 50);
		$this->desenhaLinha(self::PAGINA_LARGURA - self::MARGEM_LATERAL - $this->largura_colunas[5], self::BOLETO_INICIO + 56, self::PAGINA_LARGURA - self::MARGEM_LATERAL, self::BOLETO_INICIO + 56);

		// Verticais Finas

		// Separador Dados Bancários
		$this->desenhaLinha(self::MARGEM_LATERAL + 30, self::BOLETO_INICIO, self::MARGEM_LATERAL + 30, self::BOLETO_INICIO + 8);
		$this->desenhaLinha(self::MARGEM_LATERAL + 45, self::BOLETO_INICIO, self::MARGEM_LATERAL + 45, self::BOLETO_INICIO + 8);
		
		// Separador Dados Boleto
		$this->desenhaLinha(self::MARGEM_LATERAL + $this->largura_colunas[0], self::BOLETO_INICIO + 20, self::MARGEM_LATERAL + $this->largura_colunas[0], self::BOLETO_INICIO + 26);
		$this->desenhaLinha(self::PAGINA_LARGURA - $this->largura_colunas[5] - $this->largura_colunas[4] - $this->largura_colunas[3] - $this->largura_colunas[2] - $this->largura_colunas[1] - self::MARGEM_LATERAL, self::BOLETO_INICIO + 20, self::PAGINA_LARGURA - $this->largura_colunas[5] - $this->largura_colunas[4] - $this->largura_colunas[3] - $this->largura_colunas[2] - $this->largura_colunas[1] - self::MARGEM_LATERAL, self::BOLETO_INICIO + 32);
		$this->desenhaLinha(self::PAGINA_LARGURA - $this->largura_colunas[5] - $this->largura_colunas[4] - $this->largura_colunas[3] - $this->largura_colunas[2] - self::MARGEM_LATERAL, self::BOLETO_INICIO + 26, self::PAGINA_LARGURA - $this->largura_colunas[5] - $this->largura_colunas[4] - $this->largura_colunas[3] - $this->largura_colunas[2] - self::MARGEM_LATERAL, self::BOLETO_INICIO + 32);
		$this->desenhaLinha(self::PAGINA_LARGURA - $this->largura_colunas[5] - $this->largura_colunas[4] - $this->largura_colunas[3] - self::MARGEM_LATERAL, self::BOLETO_INICIO + 14, self::PAGINA_LARGURA - $this->largura_colunas[5] - $this->largura_colunas[4] - $this->largura_colunas[3] - self::MARGEM_LATERAL, self::BOLETO_INICIO + 32);
		$this->desenhaLinha(self::PAGINA_LARGURA - $this->largura_colunas[5] - $this->largura_colunas[4] - self::MARGEM_LATERAL, self::BOLETO_INICIO + 20, self::PAGINA_LARGURA - $this->largura_colunas[5] - $this->largura_colunas[4] - self::MARGEM_LATERAL, self::BOLETO_INICIO + 32);
		$this->desenhaLinha(self::PAGINA_LARGURA - ($this->largura_colunas[5] / 2) - self::MARGEM_LATERAL, self::BOLETO_INICIO + 8, self::PAGINA_LARGURA - ($this->largura_colunas[5] / 2) - self::MARGEM_LATERAL, self::BOLETO_INICIO + 14);

		// Separação Pagador / Sacador / Avalista
		$this->desenhaLinha(self::PAGINA_LARGURA / 2, self::BOLETO_INICIO + 62, self::PAGINA_LARGURA / 2, self::BOLETO_INICIO + 74);

	}

	function desenhaCodigoBarras() {

		$tabela = array(
			0 => "00110",
			1 => "10001",
			2 => "01001",
			3 => "11000",
			4 => "00101",
			5 => "10100",
			6 => "01100",
			7 => "00011",
			8 => "10010",
			9 => "01010"
		);

		if ((strlen($this->dados["codigo_barras"]) % 2) <> 0) {
			$this->dados["codigo_barras"] = "0{$this->dados["codigo_barras"]}";
		}
		
		$this->codigo_barras_posicao = SELF::MARGEM_LATERAL;

		$this->desenhaBarra(self::BARRA_PRETA, self::BARRA_FINA);
		$this->desenhaBarra(self::BARRA_BRANCA, self::BARRA_FINA);
		$this->desenhaBarra(self::BARRA_PRETA, self::BARRA_FINA);
		$this->desenhaBarra(self::BARRA_BRANCA, self::BARRA_FINA);

		for ($i = 0; $i < strlen($this->dados["codigo_barras"]); $i = $i + 2) {
			for ($j = 0; $j < 5; $j++) {
				$this->desenhaBarra(self::BARRA_PRETA, $tabela[$this->dados["codigo_barras"][$i]][$j]);
				$this->desenhaBarra(self::BARRA_BRANCA, $tabela[$this->dados["codigo_barras"][$i + 1]][$j]);
			}
		}

		$this->desenhaBarra(self::BARRA_PRETA, self::BARRA_LARGA);
		$this->desenhaBarra(self::BARRA_BRANCA, self::BARRA_FINA);
		$this->desenhaBarra(self::BARRA_PRETA, self::BARRA_FINA);

	}

	function desenhaBarra($cor, $tipo) {

		$largura = $tipo == self::BARRA_FINA ? 0.3 : 0.8;

		if ($cor == self::BARRA_PRETA) {
			$this->desenhaQuadrado($this->codigo_barras_posicao, 277, $largura, 15);
		}

		$this->codigo_barras_posicao += $largura;

	}

	private $chache = array();
	
	function insereImagem($tipo, $url, $x, $y, $largura, $altura) {
		
		if (!array_key_exists($url, $this->cache)) {
			$this->cache[$url] = PDF_load_image($this->pdf, $tipo, $url, "");
		}

		PDF_fit_image($this->pdf, $this->cache[$url], $this->mm2Point($x), $this->mm2Point(self::PAGINA_ALTURA - ($altura + $y)), "boxsize {{$this->mm2Point($largura)} {$this->mm2Point($altura)}} fitmethod meet");

	}

	function desenhaQuadrado($x, $y, $largura, $altura) {

		PDF_rect($this->pdf, $this->mm2Point($x), $this->mm2Point(self::PAGINA_ALTURA - ($altura + $y)), $this->mm2Point($largura), $this->mm2Point($altura));
		PDF_fill($this->pdf);

	}

	function setLarguraLinha($largura, $tracejado = false) {

		$this->largura_linha = $largura;

		PDF_setlinewidth($this->pdf, $this->mm2Point($largura));

		if ($tracejado) {
			PDF_setdash($this->pdf, $this->mm2Point(1), $this->mm2Point(1));
		} else {
			PDF_setdash($this->pdf, 0, 0);
		}

	}

	function desenhaLinha($x_inicial, $y_inicial, $x_final, $y_final) {

		$offset_y = $y_inicial == $y_final ? 0 : $this->largura_linha / 2;
		$offset_x = $x_inicial == $x_final ? 0 : $this->largura_linha / 2;

		PDF_moveto($this->pdf, $this->mm2Point($x_inicial - $offset_x), $this->mm2Point(self::PAGINA_ALTURA - $y_inicial - $offset_y));
		PDF_lineto($this->pdf, $this->mm2Point($x_final + $offset_x), $this->mm2Point(self::PAGINA_ALTURA - $y_final + $offset_y));
		PDF_stroke($this->pdf);

	}

	function setFonte($fonte, $tamanho) {

		PDF_setfont($this->pdf, $this->fontes[$fonte], $tamanho);

	}

	function escreveTexto($texto, $x, $y, $largura, $altura, $alinhamento = "left") {

		PDF_show_boxed($this->pdf, $texto,  $this->mm2Point($x), $this->mm2Point(self::PAGINA_ALTURA - ($altura + $y)), $this->mm2Point($largura), $this->mm2Point($altura), "$alinhamento", "");

	}

	function escreveWrapped($texto, $x, $y, $largura) {
		
		$largura = $this->mm2Point($largura);
		
		$fontname = PDF_get_parameter($this->pdf, "fontname", 0);
		$font = $this->fontes[$fontname];
		$size = PDF_get_value($this->pdf, "fontsize", 0);
			
		$linha = "";
		$linhas = 0;
		
		for ($i = 0; $i < strlen($texto); $i++) {
			
			$char = substr($texto, $i, 1);
			
			if (PDF_stringwidth($this->pdf, $linha, $font, $size) +
					PDF_stringwidth($this->pdf, $char, $font, $size) <= $largura) {
				$linha .= $char;
			} else {
				$this->escreveLinha($linha, $x, $y + ($size / 2.5 * $linhas));
				$linha = $char;
				$linhas++;
			}
			
		}
		
		if (strlen($linha) > 0) {
			$this->escreveLinha($linha, $x, $y + ($size / 2.5 * $linhas));
		}

	}

	function escreveLinha($texto, $x, $y, $espacamento = 0) {

		PDF_set_value($this->pdf, "charspacing", $espacamento);
		PDF_show_xy($this->pdf, $texto, $this->mm2Point($x), $this->mm2Point(self::PAGINA_ALTURA - $y));
		PDF_set_value($this->pdf, "charspacing", $espacamento);

	}

	function escreveLinhaDireita($texto, $x, $y, $espacamento = 0) {

		PDF_set_value($this->pdf, "charspacing", $espacamento);

		$fontname = PDF_get_parameter($this->pdf, "fontname", 0);
		$size = PDF_get_value($this->pdf, "fontsize", 0);
		$largura = PDF_stringwidth($this->pdf, $texto, $this->fontes[$fontname], $size);

		$this->escreveLinha($texto, $x - $this->point2MM($largura), $y, $espacamento);

	}
	
	function escreveLinhaCentro($texto, $x, $y, $espacamento = 0) {
		
		PDF_set_value($this->pdf, "charspacing", $espacamento);
		
		$fontname = PDF_get_parameter($this->pdf, "fontname", 0);
		$size = PDF_get_value($this->pdf, "fontsize", 0);
		$largura = PDF_stringwidth($this->pdf, $texto, $this->fontes[$fontname], $size);
		
		$this->escreveLinha($texto, $x - ($this->point2MM($largura) / 2), $y, $espacamento);
		
	}
	
   private static function charCodeAt($str, $i) {
	  return ord(substr($str, $i, 1));
   }

	private static function crcChecksum($str) {
	   /*
	   # Esta função auxiliar calcula o CRC-16/CCITT-FALSE
	   #
	   # Autor: evilReiko (https://stackoverflow.com/users/134824/evilreiko)
	   # Postada originalmente em: https://stackoverflow.com/questions/30035582/how-to-calculate-crc16-ccitt-in-php-hex
	   */
	  // The PHP version of the JS str.charCodeAt(i)

	   $crc = 0xFFFF;
	   $strlen = strlen($str);
	   for($c = 0; $c < $strlen; $c++) {
		  $crc ^= self::charCodeAt($str, $c) << 8;
		  for($i = 0; $i < 8; $i++) {
				if($crc & 0x8000) {
				   $crc = ($crc << 1) ^ 0x1021;
				} else {
				   $crc = $crc << 1;
				}
		  }
	   }
	   $hex = $crc & 0xFFFF;
	   $hex = dechex($hex);
	   $hex = strtoupper($hex);
	   $hex = str_pad($hex, 4, '0', STR_PAD_LEFT);

	   return $hex;
	}
	
}

